fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> Option<usize> {
    // We can perform a binary search variant to find the first occurrence efficiently
    let mut left = 0;
    let mut right = arr.len();
    while left < right {
        let mid = left + (right - left) / 2;
        if arr[mid] < target {
            left = mid + 1;
        } else {
            // arr[mid] is >= target, so narrow to left half including mid
            right = mid;
        }
    }
    // After the loop, left == right is the boundary index of target or insertion point
    if left < arr.len() && arr[left] == target {
        Some(left)
    } else {
        None
    }
}